  constructor() {
    this.confirmForm = this.attrs.confirmForm;
    window.onbeforeunload = () => {
                if (this.userService.isAuthenticated() && ((this.confirmForm && this.confirmForm.$dirty) || this.attrs.isDirty)) {
                    return this.translate.instant('confirm-on-exit.message');
                }
                return undefined;
            }
    this.confirmOnExitService.stateChangeStart$.subscribe((next?: any, current?: any, params?: any) => {
                if (this.userService.isAuthenticated() && ((this.confirmForm && this.confirmForm.$dirty) || this.attrs.isDirty)) {
                    var confirm: any = this.dialog.open(ConfirmDialogComponent, {
                        data: {
                          title: this.translate.instant('confirm-on-exit.title'),
                          htmlContent: this.translate.instant('confirm-on-exit.html-message'),
                          ariaLabel: this.translate.instant('confirm-on-exit.title'),
                          cancel: this.translate.instant('action.cancel'),
                          ok: this.translate.instant('action.ok')
                        }
                    });
                    confirm.afterClosed().subscribe((result: any) => {
                        if (result) {
                            if (this.confirmForm) {
                                this.confirmForm.$setPristine();
                            } else {
                                this.isDirty = false;
                                //$scope.isDirty = false;
                            }
                            (this.router as any).go(next.name, params);
                        }
                    });
                }
            });
  }
